//! Poseidon2 over Goldilocks, width 12 (development-only prototype).
//!
//! Parameters of the published instance (Grassi, Khovratovich, Schofnegger,
//! "Poseidon2: A Faster Version of the Poseidon Hash Function", 2023, and its
//! reference implementation's Goldilocks width-12 instance): `x^7` S-box,
//! 8 full and 22 partial rounds, the external matrix `circ(2·M4, M4, M4)` and
//! the internal matrix `J + diag(d)` with the published diagonal.
//!
//! The round constants are not transcribed: they are regenerated by the
//! published Grain LFSR procedure (`field = 1, sbox = 0, n = 64, t = 12,
//! R_F = 8, R_P = 22`) and pinned by a digest, and the permutation is pinned
//! by the reference implementation's known-answer vector for the input
//! `0, 1, .., 11`. A wrong generator, diagonal or round order fails that test.
//!
//! The round counts are the published ones; this module makes no security
//! claim for them. TODO(G.3): delete, or move the selected profile to its owner.

use std::sync::LazyLock;

use super::hash::Permutation12;
use crate::{air::PolynomialField, field::GOLDILOCKS_MODULUS_V1};

/// State width.
pub const WIDTH: usize = 12;
/// Full rounds, half before and half after the partial rounds.
pub const FULL_ROUNDS: usize = 8;
/// Partial rounds.
pub const PARTIAL_ROUNDS: usize = 22;
/// All rounds.
pub const ROUNDS: usize = FULL_ROUNDS + PARTIAL_ROUNDS;

/// Published diagonal of the internal matrix, minus one.
pub const INTERNAL_DIAGONAL_MINUS_ONE: [u64; WIDTH] = [
    0xc3b6_c08e_23ba_9300,
    0xd84b_5de9_4a32_4fb6,
    0x0d0c_371c_5b35_b84f,
    0x7964_f570_e718_8037,
    0x5daf_18bb_d996_604b,
    0x6743_bc47_b959_5257,
    0x5528_b936_2c59_bb70,
    0xac45_e25b_7127_b68b,
    0xa207_7d7d_fbb6_06b5,
    0xf3fa_ac6f_aee3_78ae,
    0x0c63_88b5_1545_e883,
    0xd27d_bb69_4491_7b60,
];

/// The published self-shrinking Grain LFSR that derives Poseidon constants.
struct Grain {
    bits: [u8; 80],
    head: usize,
}

impl Grain {
    /// Seed with the field kind, S-box kind, field bits, width and round counts.
    fn new(field_bits: usize, width: usize, full_rounds: usize, partial_rounds: usize) -> Self {
        let mut bits = [1_u8; 80];
        let mut position = 0;
        let mut push = |value: usize, width: usize| {
            for shift in (0..width).rev() {
                bits[position] = u8::from((value >> shift) & 1 == 1);
                position += 1;
            }
        };
        // Prime field, `x^alpha` S-box.
        push(1, 2);
        push(0, 4);
        push(field_bits, 12);
        push(width, 12);
        push(full_rounds, 10);
        push(partial_rounds, 10);
        let mut grain = Self { bits, head: 0 };
        for _ in 0..160 {
            grain.step();
        }
        grain
    }

    fn step(&mut self) -> u8 {
        let at = |offset: usize| self.bits[(self.head + offset) % 80];
        let bit = at(62) ^ at(51) ^ at(38) ^ at(23) ^ at(13) ^ at(0);
        self.bits[self.head] = bit;
        self.head = (self.head + 1) % 80;
        bit
    }

    /// One output bit: pairs whose first bit is zero are discarded.
    fn bit(&mut self) -> u8 {
        loop {
            let keep = self.step();
            let value = self.step();
            if keep == 1 {
                return value;
            }
        }
    }

    /// One field element: 64 bits, most significant first, rejected until canonical.
    fn element(&mut self) -> u64 {
        loop {
            let mut value = 0_u64;
            for _ in 0..64 {
                value = (value << 1) | u64::from(self.bit());
            }
            if value < GOLDILOCKS_MODULUS_V1 {
                return value;
            }
        }
    }
}

/// Round constants in round order. A partial round uses only its first word;
/// the other eleven are zero.
static ROUND_CONSTANTS: LazyLock<[[u64; WIDTH]; ROUNDS]> = LazyLock::new(|| {
    let mut grain = Grain::new(64, WIDTH, FULL_ROUNDS, PARTIAL_ROUNDS);
    let mut constants = [[0_u64; WIDTH]; ROUNDS];
    let half = FULL_ROUNDS / 2;
    for (round, row) in constants.iter_mut().enumerate() {
        if (half..half + PARTIAL_ROUNDS).contains(&round) {
            row[0] = grain.element();
        } else {
            for word in row.iter_mut() {
                *word = grain.element();
            }
        }
    }
    constants
});

/// Round constants of round `round`, in `0..ROUNDS`.
#[must_use]
pub fn round_constants(round: usize) -> &'static [u64; WIDTH] {
    &ROUND_CONSTANTS[round]
}

/// Whether round `round` applies the S-box to every word.
#[must_use]
pub const fn is_full_round(round: usize) -> bool {
    round < FULL_ROUNDS / 2 || round >= FULL_ROUNDS / 2 + PARTIAL_ROUNDS
}

/// `x^7`.
#[must_use]
pub fn sbox<F: PolynomialField>(value: F) -> F {
    let square = value.mul(value);
    let cube = square.mul(value);
    cube.mul(square.mul(square))
}

/// The 4x4 matrix `[[5,7,1,3],[4,6,1,1],[1,3,5,7],[1,1,4,6]]`.
fn m4<F: PolynomialField>(input: [F; 4]) -> [F; 4] {
    let [a, b, c, d] = input;
    let double = |value: F| value.add(value);
    let t0 = a.add(b);
    let t1 = c.add(d);
    let t2 = double(b).add(t1);
    let t3 = double(d).add(t0);
    let t4 = double(double(t1)).add(t3);
    let t5 = double(double(t0)).add(t2);
    [t3.add(t5), t5, t2.add(t4), t4]
}

/// The external linear layer `circ(2·M4, M4, M4)`.
#[must_use]
pub fn external_layer<F: PolynomialField>(state: &[F; WIDTH]) -> [F; WIDTH] {
    let mut mixed = [F::ZERO; WIDTH];
    for chunk in 0..WIDTH / 4 {
        let block = m4(core::array::from_fn(|index| state[chunk * 4 + index]));
        mixed[chunk * 4..chunk * 4 + 4].copy_from_slice(&block);
    }
    let sums: [F; 4] = core::array::from_fn(|lane| {
        (0..WIDTH / 4).fold(F::ZERO, |sum, chunk| sum.add(mixed[chunk * 4 + lane]))
    });
    core::array::from_fn(|index| mixed[index].add(sums[index % 4]))
}

/// The internal linear layer `J + diag(d)`.
#[must_use]
pub fn internal_layer<F: PolynomialField>(state: &[F; WIDTH]) -> [F; WIDTH] {
    let sum = state.iter().fold(F::ZERO, |sum, value| sum.add(*value));
    core::array::from_fn(|index| {
        state[index]
            .scale_base(INTERNAL_DIAGONAL_MINUS_ONE[index])
            .add(sum)
    })
}

/// One full round from its round constants.
#[must_use]
pub fn full_round<F: PolynomialField>(state: &[F; WIDTH], constants: &[F; WIDTH]) -> [F; WIDTH] {
    let boxed: [F; WIDTH] = core::array::from_fn(|index| sbox(state[index].add(constants[index])));
    external_layer(&boxed)
}

/// One partial round from its first round constant.
#[must_use]
pub fn partial_round<F: PolynomialField>(state: &[F; WIDTH], constant: F) -> [F; WIDTH] {
    let mut boxed = *state;
    boxed[0] = sbox(state[0].add(constant));
    internal_layer(&boxed)
}

/// Every state of one permutation: the input, the state after the initial
/// external layer and the state after each round. `ROUNDS + 2` rows.
#[must_use]
pub fn permutation_states(input: [u64; WIDTH]) -> Vec<[u64; WIDTH]> {
    let mut states = Vec::with_capacity(ROUNDS + 2);
    states.push(input);
    let mut state = external_layer(&input);
    states.push(state);
    for round in 0..ROUNDS {
        let constants = round_constants(round);
        state = if is_full_round(round) {
            full_round(&state, constants)
        } else {
            partial_round(&state, constants[0])
        };
        states.push(state);
    }
    states
}

/// The Poseidon2 permutation.
pub fn permute(state: &mut [u64; WIDTH]) {
    let mut current = external_layer(state);
    for round in 0..ROUNDS {
        let constants = round_constants(round);
        current = if is_full_round(round) {
            full_round(&current, constants)
        } else {
            partial_round(&current, constants[0])
        };
    }
    *state = current;
}

/// Poseidon2 over Goldilocks, width 12, as a sponge permutation.
#[derive(Clone, Copy, Debug, Default)]
pub struct Poseidon2Goldilocks12;

impl Permutation12 for Poseidon2Goldilocks12 {
    const NAME: &'static str = "poseidon2-goldilocks-t12-rf8-rp22-x7/sponge-r8-c4";

    fn permute(state: &mut [u64; 12]) {
        permute(state);
    }
}

#[cfg(test)]
mod tests {
    use sha2::{Digest as _, Sha256};

    use super::*;

    /// The reference implementation's vector for the input `0, 1, .., 11`.
    const KNOWN_ANSWER: [u64; WIDTH] = [
        0x01ea_ef96_bdf1_c0c1,
        0x1f0d_2cc5_25b2_540c,
        0x6282_c1df_e1e0_358d,
        0xe780_d721_f698_e1e6,
        0x280c_0b6f_753d_833b,
        0x1b94_2dd5_0231_56ab,
        0x43f0_df3f_cccb_8398,
        0xe8e8_1905_8548_9025,
        0x56bd_bf72_f77a_da22,
        0x7911_c32b_f9dc_d705,
        0xec46_7926_508f_be67,
        0x6a50_450d_df85_a6ed,
    ];

    #[test]
    fn permutation_reproduces_the_published_known_answer_vector() {
        let mut state: [u64; WIDTH] = core::array::from_fn(|index| index as u64);
        permute(&mut state);
        assert_eq!(state, KNOWN_ANSWER);
        let mut via_trait: [u64; WIDTH] = core::array::from_fn(|index| index as u64);
        Poseidon2Goldilocks12::permute(&mut via_trait);
        assert_eq!(via_trait, KNOWN_ANSWER);
        // A second pinned vector, computed with an independent script from the
        // same published parameters.
        let mut zero = [0_u64; WIDTH];
        permute(&mut zero);
        assert_eq!(zero[0], 0xef31_1849_263a_bcb4);
        assert_eq!(zero[11], 0xa08b_3351_54cb_efc5);
    }

    #[test]
    fn grain_generator_reproduces_the_published_round_constants() {
        let first = round_constants(0);
        assert_eq!(first[0], 0x13dc_f33a_ba21_4f46);
        assert_eq!(first[1], 0x30b3_b654_a1da_6d83);
        // First constant of the first and of the last partial round.
        assert_eq!(round_constants(4)[0], 0x4adf_842a_a75d_4316);
        assert_eq!(round_constants(25)[0], 0xf7bb_62a8_da4c_961b);
        assert_eq!(round_constants(26)[0], 0xc68b_e7c9_4882_a24d);
        assert_eq!(
            round_constants(ROUNDS - 1)[WIDTH - 1],
            0x962d_eba3_e9a2_cd94
        );
        let mut hasher = Sha256::new();
        for round in 0..ROUNDS {
            let constants = round_constants(round);
            assert!(constants.iter().all(|word| *word < GOLDILOCKS_MODULUS_V1));
            if !is_full_round(round) {
                assert!(constants[1..].iter().all(|word| *word == 0));
            }
            for word in constants {
                hasher.update(word.to_le_bytes());
            }
        }
        assert_eq!(
            hex::encode(hasher.finalize()),
            "c60f1566a9107aa9d9df596da06211631312b0ab018935a80d3bf0b4320d12f7"
        );
        assert_eq!(
            (0..ROUNDS).filter(|round| is_full_round(*round)).count(),
            FULL_ROUNDS
        );
    }

    #[test]
    fn linear_layers_match_their_matrices() {
        let m4_rows = [[5, 7, 1, 3], [4, 6, 1, 1], [1, 3, 5, 7], [1, 1, 4, 6_u64]];
        for column in 0..WIDTH {
            let mut unit = [0_u64; WIDTH];
            unit[column] = 1;
            let external = external_layer(&unit);
            let internal = internal_layer(&unit);
            for row in 0..WIDTH {
                let block = m4_rows[row % 4][column % 4];
                let expected = if row / 4 == column / 4 {
                    2 * block
                } else {
                    block
                };
                assert_eq!(external[row], expected, "external {row},{column}");
                let diagonal = if row == column {
                    crate::field::add_base(INTERNAL_DIAGONAL_MINUS_ONE[row], 1)
                } else {
                    1
                };
                assert_eq!(internal[row], diagonal, "internal {row},{column}");
            }
        }
        assert_eq!(sbox(3_u64), 2187);
    }

    #[test]
    fn permutation_states_end_at_the_permutation_output() {
        let input: [u64; WIDTH] = core::array::from_fn(|index| 7 * index as u64 + 3);
        let states = permutation_states(input);
        assert_eq!(states.len(), ROUNDS + 2);
        assert_eq!(states[0], input);
        assert_eq!(states[1], external_layer(&input));
        let mut output = input;
        permute(&mut output);
        assert_eq!(states[ROUNDS + 1], output);
        // Round functions are the steps between consecutive states.
        assert_eq!(states[2], full_round(&states[1], round_constants(0)));
        assert_eq!(states[6], partial_round(&states[5], round_constants(4)[0]));
    }
}
